extends "res://htd/htd_test.gd"


func _run_tests() -> void:
	var main := await instantiate_main_scene()
	if not check("main", main != null, "La scena principale deve avviarsi senza errori"):
		return
	var sprite2 := find_by_name(main, "Sprite2D2") as Sprite2D
	if not check("sprite2", sprite2 != null, "Nella scena deve esserci un nodo Sprite2D chiamato Sprite2D2"):
		return
	check("sprite2_texture", sprite2.texture != null, "A Sprite2D2 deve essere assegnata una texture")
	check("sprite2_pos", abs(sprite2.position.x - 450.0) < 5.0 and abs(sprite2.position.y - 300.0) < 5.0, "La posizione di Sprite2D2 deve essere vicina a (450, 300)")
	check("sprite2_scale", abs(sprite2.scale.x - 1.5) < 0.05 and abs(sprite2.scale.y - 1.5) < 0.05, "La scala di Sprite2D2 deve essere impostata a 1.5 su entrambi gli assi")
	check("sprite2_color", sprite2.modulate.r > 0.8 and sprite2.modulate.g < 0.2 and sprite2.modulate.b < 0.2, "Il colore Modulate di Sprite2D2 deve essere rosso")
